options.onOkButtonClick:
this.getFormRef().validateForm(res=>{
  if(!res){
    return false;
  }

  const formData = this.getFormRef().getFormData(false);
  const extraData = this.getExtraData();//获取外部带入数据对象（打开弹窗时通过打开弹窗事件带入的参数）
  const editFlag = extraData.editFlag;
  var apiName = editFlag=='add'?'add':'update';

  this.getFormRef().submitFormData(apiName).then(r=>{
    debugger;
      if(r.code != 200)
      {
        this.$message.warning(r.message);
      }
      else{
        this.$message.success("提交成功！")
        this.close();
      }
    }).catch(error=>{
      this.$message.error("提交失败！"+r.message)
      return false;
  })

})
return false;

