tableColumns.render:
//待分配1/已分配2/已下发3/取货完成4/卸货完成5/完成6/作废7
let {row, column} = params
let cellValue = row[column.prop]
let items=[{des:'未知('+cellValue+')',type:'error'},
{des:'待分配('+cellValue+')',type:''},
{des:'已分配('+cellValue+')',type:'warning'},
{des:'已下发('+cellValue+')',type:'warning'},
{des:'取货完成('+cellValue+')',type:'warning'},
{des:'卸货完成('+cellValue+')',type:'success'},
{des:'完成('+cellValue+')',type:'success'},
{des:'作废('+cellValue+')',type:'danger'}]
var targetItem=items[cellValue]

let effect='Plain';

return h(components.ElTag, {
 modelValue: cellValue,
 type:targetItem.type,
 effect:effect,
},{default:()=>targetItem.des}
)

